CREATE TABLE wm_ads_profit_estimate (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    sku_label VARCHAR(160) NULL,
    price DECIMAL(18,6) NULL,
    sales_qty DECIMAL(18,6) NULL,
    refund_rate DECIMAL(10,6) NULL,
    delivery_fee DECIMAL(18,6) NULL,
    purchase_cost DECIMAL(18,6) NULL,
    first_leg DECIMAL(18,6) NULL,
    ad_cost DECIMAL(18,6) NULL,
    exchange_rate DECIMAL(10,6) NULL,
    product_link VARCHAR(600) NULL,
    product_image VARCHAR(600) NULL,
    remark VARCHAR(1000) NULL,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    INDEX idx_profit_estimate_sku (sku_label)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


